@startuml
class Processor {
  init()
  readFromMemory()
  execute()
  loadProgram()
  writeIntoMemory()
}
interface Memory {
  read()
  wite()
}
class Cache {
  chunck
}
class RAM
Memory <|.. Cache
Memory <|.. RAM
Processor "1" *-- "1" Memory : Processor_Memory
Cache ..> RAM
@enduml

