@startuml
class Train {
  +Power : Engine
  +Manufacturer : String
  +Cars : LinkedList_Car
  +Operator : String
  addCar() : Car
}
class CargoTrain {
  +Origin : String
  +Stops : LinkedList_String
  +Containers : List_Container
  receiveCargo() : Container
  deliverCargo() : Container
}
class PassengerTrain {
  +Origin : String
  +Stops : LinkedList_String
  +numberOfPassengers : Integer
  receivePassengers() : List_String
  dropOffPassengers() : List_String
}
class FirstClass {
  +numberOfSeats : Integer
  +seatsFilled : Integer
  deliverMealService() : Boolean
  bookNewPassenger()
}
class Coach {
  +numberOfSeats : Integer
  +seatsFilled : Integer
  deliverMealService() : Boolean
  bookNewPassenger()
}
Train <|-- CargoTrain
Train <|-- PassengerTrain
PassengerTrain <|-- FirstClass
PassengerTrain <|-- Coach
@enduml

@startuml
class Match {
  -date : LocalDateTime
  -name : String
  -players : Player
  +winner : Result
  play()
  -generateMatchInformation()
  -calculateResult() : Result
}
class Player {
  -name : String
  -totalScore : Integer
  -games : Game
}
class Game {
  -number : Integer
  -score : Integer
  calculateScore()
}
class Attempt {
  number : Integer
  points : Integer
}
enum ScoreType {
  STRIKE
  SPARE
  NONE
}
class FileImporter {
  -INITIAL_DATAFILE : String
  loadData() : List_InitialData
}
class InitialData {
  -playerName : String
  -points
}
class Result {
  +player : Player
  +score : Integer
}
interface Importer {
  loadData() : List_InitialData
}
class BowlingGame {
  +attempts : List_Attempt
  scoreType : ScoreType
  previousGame : Game
  nextGames : List_Game
}
Importer <|.. FileImporter
Game <|-- BowlingGame
@enduml

